sp_widget.client_script:
function($scope, $location) {
  var c = this;

  function currentPage() {
    var q = {};
    try { q = $location.search() || {}; } catch (e) {}
    if (!q.id) {
      try {
        var m = (window.location.search || '').match(/[?&]id=([^&]+)/);
        if (m) { q.id = decodeURIComponent(m[1]); }
      } catch (e2) {}
    }
    return q.id || '';
  }
  c.page = currentPage();

  /* user chip: initials + first name from the server-provided full name */
  var full = '';
  try { full = String((c.data && c.data.user_name) || '').trim(); } catch (e3) {}
  var parts = full ? full.split(/\s+/) : [];
  c.user = { name: full, first: parts[0] || '',
             email: String((c.data && c.data.user_email) || '') };

  /* I22: account menu. Closes on outside click, on Escape, and on navigation. */
  c.userOpen = false;
  c.toggleUser = function (ev) {
    if (ev) { ev.stopPropagation(); }
    c.userOpen = !c.userOpen;
  };
  c.closeUser = function () { c.userOpen = false; };
  function onDocClick() {
    if (!c.userOpen) { return; }
    $scope.$apply(function () { c.userOpen = false; });
  }
  document.addEventListener('click', onDocClick);
  c.initials = ((parts[0] ? parts[0].charAt(0) : '') +
                (parts.length > 1 ? parts[parts.length - 1].charAt(0) : '')).toUpperCase();

  /* I21: waiting-on-you signal, straight from the server payload. The title and the
     link are read from c.signal at render time, so they always match what is shown:
     with comments waiting, the count and the awaiting filter; with none, a plain
     statement and My Engagements (the awaiting filter would be empty). */
  c.signal = (c.data && c.data.signal) || { comments: 0, records: 0 };
  c.signalTitle = function () {
    var n = c.signal.comments, r = c.signal.records;
    if (!n) { return 'No comments waiting on you'; }
    return n + ' comment' + (n === 1 ? '' : 's') + ' waiting on you across ' +
           r + ' engagement' + (r === 1 ? '' : 's');
  };
  c.signalHref = function () {
    return c.signal.comments ? '?id=ptag_status&awaiting=1' : '?id=ptag_status';
  };


  /* --- B147 #6: light/dark theme -----------------------------------------------
     Applies at once (no reload), then saves to the viewer's preference ptag.hub.theme.
     The same html[data-pt-theme] attribute is what the head boot script and the
     ptag_global link function set, and the per-user cache key is shared with them,
     so all three agree on the next page load (any device: the server value wins). */
  function readTheme() {
    var a = '';
    try { a = document.documentElement.getAttribute('data-pt-theme') || ''; } catch (e) {}
    return a === 'light' ? 'light' : 'dark';
  }
  c.theme = (c.data && (c.data.theme === 'light' || c.data.theme === 'dark')) ? c.data.theme : readTheme();
  c.themeErr = false;
  function applyTheme(t) {
    try { document.documentElement.setAttribute('data-pt-theme', t); } catch (e) {}
    try {
      var uid = (window.NOW && window.NOW.user_id) || '';
      if (uid) { window.localStorage.setItem('ptag.hub.theme.' + uid, t); }
    } catch (e2) {}
  }
  c.toggleTheme = function () {
    var next = c.theme === 'light' ? 'dark' : 'light';
    c.theme = next;
    c.themeErr = false;
    applyTheme(next);
    c.server.get({ action: 'set_theme', theme: next }).then(function (r) {
      var d = (r && r.data) || {};
      if (!d.theme_saved) { c.themeErr = true; }
    }, function () { c.themeErr = true; });
  };

  /* --- I10 mobile nav: toggle + Esc/scrim close + focus management ------- */
  c.mobileOpen = false;
  function q1(sel) { try { return document.querySelector(sel); } catch (e) { return null; } }
  c.openMobile = function () {
    c.mobileOpen = true;
    try { document.body.classList.add('pt-mobilenav-open'); } catch (e) {}
    setTimeout(function () {
      var a = q1('#pt-mobile-panel a'); if (a && a.focus) a.focus();
    }, 280);
  };
  c.closeMobile = function () {
    if (!c.mobileOpen) { return; }
    c.mobileOpen = false;
    try { document.body.classList.remove('pt-mobilenav-open'); } catch (e) {}
    setTimeout(function () {
      var b = q1('.pt-nav__burger'); if (b && b.focus) b.focus();
    }, 0);
  };
  c.toggleMobile = function () { if (c.mobileOpen) { c.closeMobile(); } else { c.openMobile(); } };
  function onKey(ev) {
    var esc = (ev.key === 'Escape' || ev.keyCode === 27);
    if (esc && c.mobileOpen) {
      $scope.$apply(function () { c.closeMobile(); });
    } else if (esc && c.userOpen) {          /* I22 */
      $scope.$apply(function () { c.closeUser(); });
    }
  }
  document.addEventListener('keydown', onKey);
  $scope.$on('$destroy', function () {
    document.removeEventListener('keydown', onKey);
    document.removeEventListener('click', onDocClick);   /* I22 */
    try { document.body.classList.remove('pt-mobilenav-open'); } catch (e) {}
  });
}

sp_widget.script:
(function() {
  /* i3 fix: scoped GlideUser has no getFullName(); use scoped-safe methods. */
  data.is_guest = !gs.getSession().isLoggedIn();
  data.user_name = '';
  if (!data.is_guest) {
    var u = gs.getUser();
    var full = '';
    try { full = String(u.getDisplayName() || ''); } catch (e1) {}
    if (!full) {
      try { full = (String(u.getFirstName() || '') + ' ' + String(u.getLastName() || '')).replace(/^\s+|\s+$/g, ''); } catch (e2) {}
    }
    if (!full) {
      try { full = String(u.getName() || ''); } catch (e3) {}
    }
    data.user_name = full;
    /* I22: the profile menu shows who you are signed in as, so it needs the address */
    try { data.user_email = String(u.getEmail() || ''); } catch (e4) { data.user_email = ''; }
  }

  /* B147 #6: the portal theme. set_theme is the only write in this widget and it only
     ever touches the viewer's OWN preference. Answers early so the toggle never waits
     on the comment signal below. */
  data.theme = 'dark';
  if (!data.is_guest) {
    try { data.theme = String(gs.getUser().getPreference('ptag.hub.theme') || '') === 'light' ? 'light' : 'dark'; } catch (eT0) {}
  }
  if (input && input.action === 'set_theme') {
    data.theme_saved = false;
    if (!data.is_guest) {
      var want = String(input.theme || '') === 'light' ? 'light' : 'dark';
      try { gs.getUser().savePreference('ptag.hub.theme', want); } catch (eT1) {}
      try { data.theme_saved = String(gs.getUser().getPreference('ptag.hub.theme') || '') === want; } catch (eT2) {}
      data.theme = want;
    }
    return;
  }

  /* I21: portal-wide "waiting on you" signal. Same PTAGCommentSignal the My
     Engagements list uses, so the header count and that list can never disagree.
     Wrapped defensively - the nav must never fail over a badge. */
  data.signal = { comments: 0, records: 0 };
  if (!data.is_guest) {
    try {
      var sg = new x_snc_ptag_engage.PTAGCommentSignal().analyzeMine();
      data.signal = { comments: sg.comments, records: sg.records };
    } catch (eSig) {}
  }
})();
